import { reviewEstimate, selectScenario } from './model.mjs';
const $=id=>document.getElementById(id);
let fixture;
let currentScenario='partial';
const copy={
 open:{label:'Resting',title:'The order is open.',description:'The synthetic book event and tracked slot agree: all 1,000 MON are still resting.',nextTitle:'What this means',next:'A successful receipt alone is not enough. The fixture reconciles the receipt, market observations and account slot before reporting an open order.',events:[['Order observed','Synthetic order 88 was created in slot 3.'],['Remainder reconciled','1,000 MON open through synthetic finalized block 105.']]},
 partial:{label:'Partial fill',title:'400 filled. 600 still open.',description:'The filled portion stays final. Only the remaining 600 MON can be considered for cancellation.',nextTitle:'Review the remainder',next:'The cancellation scenario removes 600 MON from the book. It cannot reverse the 400 MON already filled.',action:'Inspect cancelled remainder',target:'cancelled',events:[['Order observed','The fixed example starts with 1,000 MON.'],['Fill reconciled','Synthetic trade 123 accounts for 400 MON.'],['Slot checked','Order 88 remains in slot 3 with 600 MON open.']]},
 cancelled:{label:'Cancelled remainder',title:'The remainder is closed.',description:'The synthetic cancellation receipt and matching deletion agree. Filled trades remain unchanged.',nextTitle:'Cancellation does not undo a fill',next:'400 MON remain filled; 600 MON are cancelled. Released funds stay in AccountCore. This view is a recorded offline result, not an execution control.',events:[['Prior fill preserved','400 MON remain filled.'],['Cancellation correlated','The fixture ties its cancellation request to the matching receipt and tracked deletion.'],['Restart checked','Same outcome after restart; the demo makes only two fixture executor calls.']]},
 unknown:{label:'Unknown submit',title:'Stop. The outcome is unknown.',description:'A synthetic timeout happened after entering the executor. No reliable transaction hash was returned.',nextTitle:'Repeat submission refused',next:'The original service preserves the unresolved record after restart. A repeat attempt is refused because it could create a duplicate order. Keep the original request and known evidence; inspect host request status and canonical chain evidence with a human before any further action.',events:[['Executor entered','The durable pre-entry barrier was recorded.'],['Transport outcome unknown','Unknown does not mean failed, filled or cancelled.'],['Restart and retry refused','A second submit was blocked. Fixture executor calls remained at one.']]}
};
function escapeHTML(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function inputs(){return {side:document.querySelector('input[name="side"]:checked').value,price:$('price').value,quantity:$('quantity').value};}
function renderReview(){try{const r=reviewEstimate(inputs(),fixture.snapshot);$('review-output').innerHTML=`<h3>Fixture custody funding estimate</h3><div class="review-number">${escapeHTML(r.required)}<small>${r.token}</small></div><p class="review-caption">Prefunded in AccountCore · synthetic balance</p><dl class="compact-list"><div><dt>Quote notional</dt><dd>${escapeHTML(r.notional)} USDC</dd></div><div><dt>Estimated maker fee</dt><dd>${escapeHTML(r.fee)} USDC</dd></div><div><dt>Price units</dt><dd>${r.priceUnits}</dd></div><div><dt>Quantity units</dt><dd>${r.quantityUnits}</dd></div></dl><p class="review-note">Conservative snapshot estimate, not an execution-time fee cap. Wallet gas is separate. This is not a signed or saved intent.</p>`;}catch(e){$('review-output').innerHTML=`<div class="validation-message error" role="alert"><strong>Review stopped</strong>${escapeHTML(e.message)}</div>`;}}
function dirtyReview(){ $('review-output').innerHTML='<div class="validation-message"><strong>Inputs changed</strong>The previous estimate is cleared. Review these values again.</div>'; }
function setScenario(key){const s=selectScenario(fixture,key),c=copy[key];currentScenario=key;document.querySelectorAll('[data-scenario]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.scenario===key)));
 const unknown=key==='unknown';const pct=key==='open'?[0,100,0]:key==='partial'?[40,60,0]:[40,0,60];
 const amount=v=>v==='Unknown'?'Unknown':escapeHTML(v.replace(' MON',''))+' <small>MON</small>';
 $('scenario-output').innerHTML=`<div class="scenario-kicker">SYNTHETIC SCENARIO <span>/</span> ${escapeHTML(c.label.toUpperCase())}</div><h3 class="scenario-state">${c.title}</h3><p class="scenario-description">${c.description}</p><div class="ledger"><div class="ledger-item"><div class="ledger-label">Filled</div><div class="ledger-value">${amount(s.filled)}</div></div><div class="ledger-item"><div class="ledger-label">Open</div><div class="ledger-value">${amount(s.open)}</div></div><div class="ledger-item"><div class="ledger-label">Cancelled</div><div class="ledger-value">${amount(s.cancelled)}</div></div></div><div class="distribution ${unknown?'unknown':''}" aria-hidden="true">${unknown?'':`<span class="filled" style="width:${pct[0]}%"></span><span class="open" style="width:${pct[1]}%"></span><span class="cancelled" style="width:${pct[2]}%"></span>`}</div><p class="distribution-caption">${unknown?'No quantity outcome can be asserted from this evidence.':'1,000 MON total · recorded fixture quantities conserve the original size'}</p><div class="next-step ${unknown?'refusal':''}"><h3>${c.nextTitle}</h3><p>${c.next}</p>${c.action?`<button type="button" id="inspect-cancel">${c.action}</button>`:''}</div><div class="event-list">${c.events.map((e,i)=>`<div class="event-row"><span class="event-index">${i+1}</span><div><strong>${e[0]}</strong><p>${e[1]}</p></div></div>`).join('')}</div>`;
 $('scenario-evidence').replaceChildren();const intro=document.createElement('p');intro.textContent=unknown?'Exported from the original OrderService with a throwing synthetic executor, followed by a restarted repeat request. No network or wallet was involved.':'Exported from the original OrderService and presentStatus using OfflineDemoChain. All blocks, slots, orders, hashes and fills in this scenario are synthetic.';const pre=document.createElement('pre');pre.textContent=JSON.stringify(s,null,2);$('scenario-evidence').append(intro,pre);$('inspect-cancel')?.addEventListener('click',()=>setScenario('cancelled'));
}
async function start(){try{const r=await fetch('./evidence.json');if(!r.ok)throw Error('Fixture file unavailable');fixture=await r.json();renderReview();setScenario(currentScenario);$('public-check').textContent=`Saved check: ${fixture.publicRead.checkedAt.replace('T',' ').replace('Z',' UTC')} · Monad testnet 10143 · block ${fixture.publicRead.blockNumber}. The fixed market, custody and implementation addresses matched the documented deployment.`;$('review-form').addEventListener('submit',e=>{e.preventDefault();renderReview();});$('review-form').addEventListener('input',dirtyReview);document.querySelectorAll('[data-scenario]').forEach(b=>b.addEventListener('click',()=>setScenario(b.dataset.scenario)));$('reset').addEventListener('click',()=>{$('review-form').reset();renderReview();setScenario('partial');document.querySelectorAll('details').forEach(d=>d.open=false);});}catch(e){$('review-output').innerHTML='<div class="validation-message error" role="alert">Offline fixture could not load. No actions are available. Reload to try again.</div>';$('scenario-output').textContent='Scenario evidence unavailable';document.querySelectorAll('.workspace button, #reset').forEach(b=>b.disabled=true);}}
function openDemo(){const panel=$('offline-examples');panel.open=true;panel.scrollIntoView({block:'start'});}
$('try-demo').addEventListener('click',openDemo);
if(location.hash==='#offline-examples')openDemo();
start();
